namespace {

struct CompletionUse {
  const FieldDecl *Field;
  const ValueDecl *Base;
};

static const Expr *stripAddressAndCasts(const Expr *E) {
  if (!E)
    return nullptr;

  E = E->IgnoreParenImpCasts();
  while (const auto *UO = dyn_cast<UnaryOperator>(E)) {
    if (UO->getOpcode() != UO_AddrOf)
      break;
    E = UO->getSubExpr()->IgnoreParenImpCasts();
  }
  return E;
}

static const ValueDecl *getRootDecl(const Expr *E) {
  E = stripAddressAndCasts(E);
  if (!E)
    return nullptr;

  if (const auto *DRE = dyn_cast<DeclRefExpr>(E))
    return DRE->getDecl();

  if (const auto *ME = dyn_cast<MemberExpr>(E))
    return getRootDecl(ME->getBase());

  if (const auto *ASE = dyn_cast<ArraySubscriptExpr>(E))
    return getRootDecl(ASE->getBase());

  return nullptr;
}

static bool getCompletionUse(const Expr *E, CompletionUse &Use) {
  E = stripAddressAndCasts(E);
  const auto *ME = dyn_cast_or_null<MemberExpr>(E);
  if (!ME)
    return false;

  const auto *Field = dyn_cast<FieldDecl>(ME->getMemberDecl());
  const ValueDecl *Base = getRootDecl(ME->getBase());
  if (!Field || !Base)
    return false;

  Use = {Field->getCanonicalDecl(), Base->getCanonicalDecl()};
  return true;
}

static bool sameCompletion(const CompletionUse &L, const CompletionUse &R) {
  return L.Field == R.Field && L.Base == R.Base;
}

class WorkerCallVisitor
    : public RecursiveASTVisitor<WorkerCallVisitor> {
public:
  bool VisitCallExpr(CallExpr *CE) {
    const FunctionDecl *Callee = CE->getDirectCallee();
    if (!Callee || CE->getNumArgs() == 0)
      return true;

    const IdentifierInfo *II = Callee->getIdentifier();
    if (!II)
      return true;

    StringRef Name = II->getName();
    const Expr *Arg = CE->getArg(0);

    if (Name == "complete" || Name == "completion_done") {
      CompletionUse Use;
      if (getCompletionUse(Arg, Use)) {
        if (Name == "complete")
          CompleteUses.push_back(Use);
        else
          DoneUses.push_back(Use);
      }
    } else if (Name == "kfree") {
      if (const ValueDecl *Base = getRootDecl(Arg))
        FreedBases.push_back(Base->getCanonicalDecl());
    }

    return true;
  }

  bool hasUnguardedFreedCompletion() const {
    for (const CompletionUse &Complete : CompleteUses) {
      bool ContextFreed = false;
      for (const ValueDecl *FreedBase : FreedBases) {
        if (FreedBase == Complete.Base) {
          ContextFreed = true;
          break;
        }
      }
      if (!ContextFreed)
        continue;

      bool HasGuard = false;
      for (const CompletionUse &Done : DoneUses) {
        if (sameCompletion(Complete, Done)) {
          HasGuard = true;
          break;
        }
      }
      if (!HasGuard)
        return true;
    }

    return false;
  }

private:
  llvm::SmallVector<CompletionUse, 4> CompleteUses;
  llvm::SmallVector<CompletionUse, 4> DoneUses;
  llvm::SmallVector<const ValueDecl *, 4> FreedBases;
};

