  if (const auto *ME = dyn_cast<MemberExpr>(E))
    return getRootDecl(ME->getBase());

  if (const auto *ASE = dyn_cast<ArraySubscriptExpr>(E))
    return getRootDecl(ASE->getBase());

  return nullptr;
}

static bool getCompletionUse(const Expr *E, CompletionUse &Use) {
  E = stripAddressAndCasts(E);
  const auto *ME = dyn_cast_or_null<MemberExpr>(E);
  if (!ME)
    return false;

  const auto *Field = dyn_cast<FieldDecl>(ME->getMemberDecl());
  const ValueDecl *Base = getRootDecl(ME->getBase());
  if (!Field || !Base)
    return false;

  Use = {cast<FieldDecl>(Field->getCanonicalDecl()),
         cast<ValueDecl>(Base->getCanonicalDecl())};
  return true;
}

static bool sameCompletion(const CompletionUse &L, const CompletionUse &R) {
  return L.Field == R.Field && L.Base == R.Base;
}

class CompletionDoneVisitor
    : public RecursiveASTVisitor<CompletionDoneVisitor> {
public:
  bool VisitCallExpr(CallExpr *CE) {
    const FunctionDecl *Callee = CE->getDirectCallee();
    if (!Callee || CE->getNumArgs() == 0)
      return true;

    const IdentifierInfo *II = Callee->getIdentifier();
    if (!II || II->getName() != "completion_done")
      return true;

    CompletionUse Use;
    if (getCompletionUse(CE->getArg(0), Use))
      Uses.push_back(Use);

    return true;
  }

  llvm::ArrayRef<CompletionUse> getUses() const { return Uses; }

private:
  llvm::SmallVector<CompletionUse, 4> Uses;
};

class WorkerCallVisitor : public RecursiveASTVisitor<WorkerCallVisitor> {
public:
  bool TraverseIfStmt(IfStmt *If) {
    if (!If)
      return true;

    if (If->getInit() && !TraverseStmt(If->getInit()))
      return false;

    if (If->getConditionVariableDeclStmt() &&
        !TraverseStmt(If->getConditionVariableDeclStmt()))
      return false;

    if (!TraverseStmt(If->getCond()))
      return false;

    CompletionDoneVisitor ConditionVisitor;
    ConditionVisitor.TraverseStmt(If->getCond());

    const size_t PreviousGuardCount = Guards.size();
    Guards.append(ConditionVisitor.getUses().begin(),
                  ConditionVisitor.getUses().end());

    if (!TraverseStmt(If->getThen())) {
      Guards.resize(PreviousGuardCount);
      return false;
    }

    if (If->getElse() && !TraverseStmt(If->getElse())) {
      Guards.resize(PreviousGuardCount);
      return false;
    }

    Guards.resize(PreviousGuardCount);
    return true;
  }

  bool VisitCallExpr(CallExpr *CE) {
    const FunctionDecl *Callee = CE->getDirectCallee();
    if (!Callee || CE->getNumArgs() == 0)
      return true;

    const IdentifierInfo *II = Callee->getIdentifier();
    if (!II)
      return true;

    StringRef Name = II->getName();
    const Expr *Arg = CE->getArg(0);

    if (Name == "complete") {
      CompletionUse Use;
      if (!getCompletionUse(Arg, Use))
        return true;

      CompleteUses.push_back(Use);
      if (!isGuarded(Use) && !UnguardedComplete)
        UnguardedComplete = CE;
    } else if (Name == "kfree") {
      if (const ValueDecl *Base = getRootDecl(Arg))
        FreedBases.push_back(cast<ValueDecl>(Base->getCanonicalDecl()));
    }

    return true;
  }

  const CallExpr *getUnguardedFreedCompletion() const {
    if (!UnguardedComplete)
      return nullptr;

    for (const CompletionUse &Complete : CompleteUses) {
      if (!sameCompletion(Complete, getUseForCall(UnguardedComplete)))
        continue;

      for (const ValueDecl *FreedBase : FreedBases) {
        if (FreedBase == Complete.Base)
          return UnguardedComplete;
      }
    }

    return nullptr;
  }

private:
  bool isGuarded(const CompletionUse &Use) const {
    for (const CompletionUse &Guard : Guards) {
      if (sameCompletion(Use, Guard))
        return true;
    }
    return false;
  }

  static CompletionUse getUseForCall(const CallExpr *CE) {
    CompletionUse Use = {nullptr, nullptr};
    if (CE && CE->getNumArgs() > 0)
      getCompletionUse(CE->getArg(0), Use);
    return Use;
  }

  llvm::SmallVector<CompletionUse, 4> Guards;
  llvm::SmallVector<CompletionUse, 4> CompleteUses;
  llvm::SmallVector<const ValueDecl *, 4> FreedBases;
  const CallExpr *UnguardedComplete = nullptr;
};

class SAGenTestChecker : public Checker<check::ASTCodeBody> {
  mutable std::unique_ptr<BugType> BT;

public:
  SAGenTestChecker()
      : BT(new BugType(this, "Workqueue timed-wait UAF risk",
                       "Concurrency")) {}

  void checkASTCodeBody(const Decl *D, AnalysisManager &Mgr,
                        BugReporter &BR) const;

private:
  bool isWorkerFunction(const FunctionDecl *FD) const;
};

bool SAGenTestChecker::isWorkerFunction(const FunctionDecl *FD) const {
  if (!FD)
    return false;

  for (const ParmVarDecl *P : FD->parameters()) {
    QualType QT = P->getType();
    if (!QT->isPointerType())
      continue;

    QualType Pointee = QT->getPointeeType();
    if (const RecordType *RT = Pointee->getAs<RecordType>()) {
      const RecordDecl *RD = RT->getDecl();
      const IdentifierInfo *II = RD->getIdentifier();
      if (II && II->getName() == "work_struct")
        return true;
    }
  }

  return false;
}

void SAGenTestChecker::checkASTCodeBody(const Decl *D, AnalysisManager &Mgr,
                                        BugReporter &BR) const {
  const auto *FD = dyn_cast<FunctionDecl>(D);
  if (!FD || !FD->hasBody() || !isWorkerFunction(FD))
    return;

  WorkerCallVisitor Visitor;
  Visitor.TraverseStmt(FD->getBody());

  const CallExpr *UnguardedComplete =
      Visitor.getUnguardedFreedCompletion();
  if (!UnguardedComplete)
    return;

  BR.EmitBasicReport(
      FD, this, "Workqueue timed-wait UAF risk", "Concurrency",
      "Worker completes a context that it may free without a matching "
      "completion_done() guard",
      PathDiagnosticLocation::createBegin(UnguardedComplete,
                                          BR.getSourceManager()));
}

} // namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker",
      "Detects a worker completing a context it may free without a "
      "matching completion_done() guard",
      "");
}

