// Return the last occurrence of a lock operation before Offset whose nearby
// source text names tx_lock. This also covers irqsave variants.
static size_t LastTxLockOperation(StringRef Text, StringRef Operation,
                                 size_t Offset) {
  size_t Pos = Text.rfind(Operation, Offset);
  while (Pos != StringRef::npos) {
    size_t End = std::min(Text.size(), Pos + 160);
    if (Text.slice(Pos, End).contains("tx_lock"))
      return Pos;
    if (Pos == 0)
      break;
    Pos = Text.rfind(Operation, Pos - 1);
  }
  return StringRef::npos;
}

