    return false;

  // Only accept a free nested inside the actual target-list traversal.
  if (const ForStmt *FS =
          findSpecificTypeInParents<ForStmt>(CallOrigin, C))
    if (ContainsListAndTxTarget(FS, C))
      return true;

  if (const WhileStmt *WS =
          findSpecificTypeInParents<WhileStmt>(CallOrigin, C))
    if (ContainsListAndTxTarget(WS, C))
      return true;

  if (const DoStmt *DS =
          findSpecificTypeInParents<DoStmt>(CallOrigin, C))
    if (ContainsListAndTxTarget(DS, C))
      return true;

  return false;
}

bool SAGenTestChecker::isFalsePositive(const Stmt *CallOrigin,
                                       CheckerContext &C) const {
  if (!CallOrigin)
    return false;

  const LocationContext *LCtx = C.getLocationContext();
  const auto *FD =
      dyn_cast_or_null<FunctionDecl>(LCtx ? LCtx->getDecl() : nullptr);
  if (!FD || !FD->hasBody())
    return false;

  const SourceManager &SM = C.getSourceManager();
  const LangOptions &LangOpts = C.getLangOpts();
  const Stmt *Body = FD->getBody();

  CharSourceRange BodyRange =
      CharSourceRange::getTokenRange(Body->getSourceRange());
  StringRef BodyText = Lexer::getSourceText(BodyRange, SM, LangOpts);
  if (BodyText.empty())
    return false;

  SourceLocation BodyBegin = SM.getSpellingLoc(Body->getBeginLoc());
  SourceLocation FreeLoc = SM.getSpellingLoc(CallOrigin->getBeginLoc());
  if (BodyBegin.isInvalid() || FreeLoc.isInvalid() ||
      SM.getFileID(BodyBegin) != SM.getFileID(FreeLoc))
    return false;

  unsigned BodyOffset = SM.getFileOffset(BodyBegin);
  unsigned FreeOffset = SM.getFileOffset(FreeLoc);
  if (FreeOffset < BodyOffset)
    return false;

  size_t RelativeFreeOffset = FreeOffset - BodyOffset;
  if (RelativeFreeOffset >= BodyText.size())
    return false;

  StringRef BeforeFree = BodyText.take_front(RelativeFreeOffset);

  // A scoped guard keeps tx_lock held until its enclosing scope exits. For the
  // target list cleanup, the guard is in the same function scope as the frees.
  size_t GuardPos = BeforeFree.rfind("guard(spinlock_irqsave)");
  if (GuardPos != StringRef::npos &&
      BeforeFree.slice(GuardPos, BeforeFree.size()).contains("tx_lock"))
    return true;

  // For explicit locking, the most recent tx_lock operation determines whether
  // the lock is held at this free. Include irqsave/irqrestore spellings.
  size_t LockPos = LastTxLockOperation(BeforeFree, "spin_lock",
                                       BeforeFree.size());
  size_t RawLockPos = LastTxLockOperation(BeforeFree, "raw_spin_lock",
                                          BeforeFree.size());
  if (RawLockPos != StringRef::npos &&
      (LockPos == StringRef::npos || RawLockPos > LockPos))
    LockPos = RawLockPos;

  size_t UnlockPos = LastTxLockOperation(BeforeFree, "spin_unlock",
                                         BeforeFree.size());
  size_t RawUnlockPos = LastTxLockOperation(BeforeFree, "raw_spin_unlock",
                                            BeforeFree.size());
  if (RawUnlockPos != StringRef::npos &&
      (UnlockPos == StringRef::npos || RawUnlockPos > UnlockPos))
    UnlockPos = RawUnlockPos;

  return LockPos != StringRef::npos &&
         (UnlockPos == StringRef::npos || LockPos > UnlockPos);
}

