  const Expr *Origin = Call.getOriginExpr();
  if (!Origin) return false;
  // Match spin_unlock*, raw_spin_unlock*
  return ExprHasName(Origin, "spin_unlock", C) || ExprHasName(Origin, "raw_spin_unlock", C);
